# AUTO-MIGRIERT auf Code-Schluessel (migrate_keys.py).
# Keys: (pfad_oder_basename, "Feld#c:CODE") bzw. "Feld#r:ZEILE" (Quellzeile ohne Code).

DE_IMAONLY_EM = {
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_0'): 'Die dämonische Präsenz in diesem Gebiet ist\ndurch deine Bemühungen geschwächt,\nLady Sakuna.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_1'): 'Oho! "Dank mir" ist wohl wahr!\nIch verdiene stehenden Applaus!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_2'): 'Es könnte Zeit sein, den Wald\nins Visier zu nehmen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_3'): 'Den da drüben?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_4'): 'Ich bin nicht sicher, was "da drüben"\nbedeuten soll, aber ja.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_5'): 'Kontrollieren wir den östlichen Wald, sollten wir alles\nbesorgen können, was wir zum Leben auf dieser Insel brauchen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_6'): 'Mrrrgh... Ich würde lieber weitere\nschwer abarbeitbare Tätigkeiten vermeiden,\naber ohne Essen zu leben ist das Übelere.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_7'): 'In der Tat! Hunger ist Grausamkeit in Person!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_8'): 'DU bist sicher keine, die sprechen darf,\ndu gefräßiger Tor.\nLerne, dich zurückzuhalten.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:020001aa_9'): 'Bwah?!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_0'): 'Was bitte sollen das hier sein?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_1'): 'Was, deine Augen sind plötzlich kaputt?\nDas sind Tekusari-Knödel.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_10'): 'Ich habe dieses ganze Jahr gearbeitet, wie man mir sagte!\nTag für Tag jagte ich, pflegte die Felder\nund hielt euch im Auge...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_11'): 'Und als Belohnung für meine schwerste Arbeit\nbekomme ich dieses ungenießbare Abfallprodukt?! \nIst die Welt verrückt geworden?!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_12'): 'Es hat sich überhaupt nichts verbessert!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_13'): 'Hah. Jammere, so viel du willst, Madam Hoch und\nMächtig. Wir haben kein Fleisch und kein Gemüse,\nalso sei dankbar für alles, was auf deinen Teller kommt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_14'): 'Ich finde es eigentlich ziemlich lecker.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_15'): 'Oooh!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_16'): '*schnüff* Waaaaaah!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_17'): 'Prinzessin! Wo denkst du hin, wohin du willst?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_2'): 'Myrthe und ich haben sie gemacht. Wollen wir bis\nnächstes Jahr überleben, können wir den Magen\nnicht nur mit Reis füllen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_3'): 'Ist "kusari" nicht das Wort für verfault in Yanato?\nDas klingt nicht gerade appetitlich.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_4'): 'In meiner Heimat nannten wir sie\n"Rotes Spinnenlilien-Knödel."',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_5'): 'Die Spinnenlilie selbst ist eine Giftpflanze,\naber zerdrückt man die Wurzeln und weicht sie\nin Wasser ein, erhält man diese...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_6'): 'AAAGH! Das war mir schon zu viel!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_7'): 'Was wäre tragischer als jemand meines\nedlen Standes, der auf diese abgelegene\nInsel verbannt und mit giftigen Knödeln gefüttert wird?!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_8'): 'Mein Kochen... kein Gift...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000201_9'): 'Lady Sakuna, das Gift wurde entfernt!\nMach dir keine Sorgen, Myrthe. Ein kurzes\nAusspülen macht sie wieder gut.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_0'): 'Dank deiner mutigen Bemühungen, Lady Sakuna,\nhaben wir seit Langem keinen Mangel an Essen mehr.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_1'): 'Ich danke dir von ganzem Herzen,\ndass du uns Tag für Tag schützt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_10'): 'Wie auch immer, ich wusste es immer,\naber ich bin tatsächlich so erstaunlich, wie du sagst.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_11'): 'Welche andere Gottheit vereint die Kampfkunst\neines Kriegsgottes und die Gunst einer\nErntegöttin mit solch blendender Begabung?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_12'): 'Von nun an herrsche ich mit absoluter\nSouveränität! Bwahahaha!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_13'): 'Göttin, ich freue mich, dass du glücklich bist, aber bitte...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_14'): 'Oh, komm. Du hast noch nicht einmal den\nwichtigen kaiserlichen Erlass erledigt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_15'): 'Wenn du dich darum nicht kümmerst,\ngeht es nicht zurück in die Hauptstadt, oder?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_16'): 'Sakuna kann nicht zurückkehren.\nWir können nicht zurückkehren.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_17'): 'Aaargh. Ich glaube, das stimmt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_18'): 'Was lässt die Dämonen auf dieser Insel\nunaufhörlich zunehmen? Das zu entdecken,\nbleibt deine heilige Aufgabe, meine Frau.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_19'): 'Solange uns der Schlüssel zu diesem Rätsel fehlt,\nhaben wir keine andere Wahl, als dieses\ngeheimnisvolle Eiland weiter zu erkunden.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_2'): 'Bwahaha! Erlebt die Allmacht einer Göttin!\nÜberschüttet mich mit Lob, Menschenkinder!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_20'): 'Wir waren noch nicht beim... südlichen Vulkan,\nder westlichen Festung oder dem nördlichen Tal.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_21'): 'Von diesen stellt die westliche Festung\ndie größte Herausforderung dar.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_22'): 'Sie wurde lange gebaut, in der Zeit, als Lord\nTakeribi mit der früheren\nKamuhitsuki Krieg führte. Nun ist sie ein Bollwerk der Dämonen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_23'): 'Ein gemeiner, schauderhafter Hauch von Bosheit\nweht über die Hügel wie ein giftiger Windhauch.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_24'): 'Igitt! Ich kann damit noch nicht konkurrieren.\nKönigliche Prokrastination ist die Devise des Tages!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_25'): 'Wenn schon vom südlichen Vulkan die Rede ist, spüre ich\ndort tatsächlich sehr wenig dämonische Präsenz.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_26'): 'Vielleicht haben die giftigen Gase, die vom\nBergaufwand steigen, sie abgeschreckt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_27'): 'Mit anderen Worten, es bleibt mir, das nördliche\nTal zu untersuchen, danach muss ich alle\nmeine Kraft mobilisieren und die Festung belagern.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_28'): 'Es ist wie du sagst.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_29'): 'Mögest du in allem siegreich sein.\nWir werden unser Bestes tun, dich zu unterstützen,\nLady Sakuna.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_3'): 'Ja, meine Frau!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_30'): 'Jaa, jaa!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_31'): 'Hm? Hast du eine Erkenntnis, Kaimaru?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_32'): 'Wheehee!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_33'): 'Dieser Kerl ist nutzlos!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_4'): 'Prinzessin...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_5'): 'Was? Willst du mich wieder zurechtweisen?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_6'): 'Nein, nein. Absolut nicht.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_7'): 'Es ist nur... Emotion überkommt mich,\nwenn ich bedenke, wie viel Not meine verwöhnte\nkleine Prinzessin hier erduldet hat. Ich bin... so stolz...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_8'): 'Wahrlich, das Glück schwillt in meiner Brust...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:02000501_9'): 'Igitt... Du hast eine Gabe,\nDinge merkwürdig zu machen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_0'): 'Unglaublich. Wenn du also dieses "Druckpresse"-\nObjekt benutzt, kannst du so viele Bücher machen, wie du willst?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_1'): 'Ja! Ich werde alles, was ich sehe, in Bücher bringen\nund es meiner Heimat erzählen, Ventania.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_10'): 'Bwaaah?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_11'): 'Wenn die Schwebende Brücke des Himmels\nsich erneut manifestieren würde, könntest du nach Hause.\nJedoch...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_12'): 'Solche Tat liegt selbst jenseits der Reichweite der Götter.\nIch habe Gerüchte gehört, dass nur die allererste\nKamuhitsuki sie nach Belieben kontrollieren konnte.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_13'): 'Nun erscheint und verschwindet sie einfach\ngeheimnisvoll, wie ein vorüberziehender Nebel.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_14'): 'Sag, Tama. Meine Mutter war ursprünglich ein Mensch.\nMit anderen Worten, sie stammte aus dem Niedrigen Reich.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_15'): 'Wie ist sie ins Erhabene Reich gelangt?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_16'): 'Deine Mutter, Lady Toyohana, hat die Passage offensichtlich\nnicht über die Schwebende Brücke des Himmels,\nsondern mit dem Göttlichen Gewand gemacht, das du nun trägst.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_17'): 'Oh, dieses uralte Gewand? Und ich dachte,\nes taugt nur dazu, Kiesel zu fegen,\ndie es wagen, mir den Weg zu versperren...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_18'): 'Hmmm... Warte.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_19'): 'Bedeutet das also, dass dieses Gewand,\nin gewissem Sinne, mächtiger ist als\ndie jetzige Lady Kamuhitsuki?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_2'): 'Nee, ich erzähle es der Welt!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_20'): 'Auf eine gewisse Art, ja.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_21'): 'Wie Lady Toyohana an ein solch mächtiges\nObjekt im Niedrigen Reich kam...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_22'): 'Weder ich noch gar dein Vater,\nLord Takeribi, kennen die Antwort.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_23'): 'Ich verstehe. Wie auch immer, unsere einzige andere Hoffnung\nliegt darin, dass ich den Gebrauch dieses Gewands beherrsche.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_24'): 'Ich würde sagen, du hast recht.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_25'): 'Jedoch, Prinzessin... Wenn du stärker werden willst,\nmusst du bereit sein, ein\ngeeignetes Opfer zu bringen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_26'): 'Hast du den Entschluss, etwas zu verlieren,\ndas ebenso wertvoll ist wie die Kraft,\nzwischen den Reichen zu reisen?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_27'): 'S-Sei nicht lächerlich. Ich hasse Gefahr.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_28'): 'Dann solltest du dich vorerst darauf konzentrieren,\ndie Verzeihung von Lady Kamuhitsuki zu verdienen,\nindem du die Pflicht erfüllst, die sie dir anvertraut hat.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_29'): 'Dann, sobald die Brücke erneut erscheint,\nkannst du sie um die Antworten bitten, die du suchst.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_3'): 'Das Land Yanato ist heel goed!\nSehr gut!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_30'): 'Mrrrgh...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_4'): 'Ich denke, das ist das erste Mal, dass ich\nMyrthe so aufgeregt sehe.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_5'): 'Ja, aber... um das zu tun,\nmüssen wir irgendwann ins Niedrige Reich zurück.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_6'): 'Keiner von uns ist hier, weil wir es wollen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_7'): 'Du hast recht.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_8'): 'Der arme Kaimaru wurde entführt,\nbevor er viel vom Niedrigen Reich kannte.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:03000101_9'): 'Auf dieser Insel isoliert aufzuwachsen,\nwäre zu grausames Schicksal für dieses arme Kind...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_0'): 'Nun, es wurde hier auf Hinoe geerntet,\nalso nenne es "Hinoe-Reis" oder so.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_1'): 'Zu offensichtlich! Nächster!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_10'): '*seufz* In der Tat, ich war töricht, mich bei\neiner intellektuellen Aufgabe wie dieser auf Bauern zu verlassen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_11'): 'Ich bin eine Meisterin der Worte nach dem Lesen aller\ntausendzweihundert Bände von Oborozuki Koushis\n"Eine Geschichte unerwidelter Liebe."',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_12'): 'Hmmm... Unser Reis ist klar der beste im gesamten\nErhabenen Reich, also sollte unsere Marke\ndas Wort "himmlisch" enthalten.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_13'): 'Himmlisch... Reis...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_14'): 'Das ist es! Wie wäre es mit\n"Verehrte Ähren des Himmels"?!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_15'): 'Verehrte Ähren!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_16'): 'Was?!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_17'): 'Verehrte Ähren, hm? Nicht schlecht.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_18'): 'Es ist leicht zu merken.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_19'): 'Mir gefällt es auch!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_2'): 'Was ist mit "Frucht der Fleißigen Studie"?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_20'): 'Igitt, wie wagst du es!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_21'): 'Verehrte Ähren ist in Ordnung. Es klingt vielleicht\nnicht landwirtschaftlich, aber es hat einen gewissen Klang.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_22'): 'Eine solche Marke passt perfekt zu dir, Lady Sakuna.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_23'): 'D-Denkst du das? Nun, in dem Fall,\nkann ich mich wohl... damit abfinden...?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_24'): 'Von nun an wird unser Reis in der\nHauptstadt als Verehrte Ähren verkauft. Nun können wir Gegenstände\nerhalten, die es auf dieser Insel nicht gibt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_25'): 'Yeaaah!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_26'): 'Juhu!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_27'): 'Etwas an der Art, wie das ablief,\nmacht mir das Gefühl, dass ich überrannt wurde...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_3'): 'Dieser Name erzählt die Geschichte einer Gruppe,\ndie in einem fernen und unvertrauten Land\njede Not überwand, um Reichtum aufzubauen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_4'): 'Zu verschachtelt. Mach es einfacher. Nächster!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_5'): 'Äh, eine Göttin hat es gemacht, also wie wäre es mit\n"Göttlicher Reis"?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_6'): 'Die, die es kaufen, sind auch Götter. Nächster!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_7'): '"Sakuna Ontembaar"!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_8'): 'Ich habe keine Ahnung, was du sagst. Nächster!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:04010101_9'): 'Hör auf, dich auf uns zu verlassen, und denk\ndir selbst etwas aus, dann!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_0'): 'S-Schon wieder die Tekusari-Knödel?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_1'): 'Wir haben wieder kein Fleisch und kein Gemüse.\nZumindest füllt das hier deinen Magen!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_10'): 'Ich wohl... *hust*',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_11'): 'Zum Gedenken an unser Durchhaltevermögen\ntaufe ich diese Tekusari-Knödel\nmit einem neuen Namen: "Wiedergeburtsknödel."',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_12'): 'Auf neue Anfänge! Lasst uns schmausen!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_13'): 'Alle, erhebt eure Becher!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_14'): 'Yeaaah!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_15'): 'Unsere neue Ernte wird reichlicher sein als je zuvor!\nFür die Herrlichkeit des Reises!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_16'): 'Für die Herrlichkeit des Reiiises!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_2'): 'Das habe ich gesagt! Sei nicht so ein Nachahmer!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_3'): 'Die mag ich.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_4'): 'Der ist meiner!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_5'): 'Oooh, oooh!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_6'): 'Kaimaru ist der Einzige auf meiner Seite!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_7'): 'Nun, es können raue Tage bevorstehen, aber...',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_8'): 'Zumindest heute Abend lachen wir\nund machen fröhliche Miene.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:05000705_9'): 'Prinzessin, du solltest auch etwas sagen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_0'): 'Das ist also die Verwandlungskugel?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_1'): 'Was ist das?\nIst das nicht der Amal-Stein?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_10'): 'Na gut, Ehrlichkeit ist nicht immer die beste Politik.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_11'): 'Du bist nicht besser! Du könntest versuchen,\nnicht zwischen jedem zweiten Atemzug zu klagen!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_12'): 'So, so. Das Essen wird kalt.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_13'): 'Juhu!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_2'): 'Der "Amal-Stein"? Was ist das?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_3'): 'Als wir Missionare von Formos zu reisen begannen,\nhielten wir in einem Königreich namens Dharka.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_4'): 'Dort fanden wir einen großen Baum namens Jomon-Baum.\nDas Volk und der Wald stritten sich um einen roten Stein.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_5'): 'Ein roter Stein und ein Riesenbaum, hm?\nDas klingt tatsächlich so, als könnte es zusammenhängen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_6'): 'Und, was wirst du mit diesem Stein tun?',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_7'): 'Hm? Wie, ich werde ihn zermalmen, mit\ndem Dünger mischen und auf den Boden gießen.',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_8'): 'Eklig! Sprich nicht über solche Sachen,\nwährend wir essen!',
    ('Text/Event/Mura/ImaOnly/EventMain.csvtxt', 'English#c:06000601_9'): 'Mache mir keine Vorwürfe. Ich habe lediglich\neine Frage beantwortet.',
}

